settings.custom_liquid:
{%- assign img = collection.image -%}
{%- assign heading = collection.title -%}

{%- if img != blank -%}
<div id="cbpx" class="cbpx" data-cbp-factor="0.25">
  <img class="cbpx__img"
       src="{{ img | image_url: width: 2000 }}"
       srcset="{{ img | image_url: width: 800 }} 800w, {{ img | image_url: width: 1400 }} 1400w, {{ img | image_url: width: 2000 }} 2000w"
       sizes="100vw" alt="{{ heading | escape }}" loading="eager">
  <div class="cbpx__overlay"></div>
  <div class="cbpx__content"><h1 class="cbpx__title">{{ heading }}</h1></div>
</div>

<style>
  #cbpx { position: relative; width: 100%; overflow: hidden; height: 320px; background: #0B1120; display: block; }
  #cbpx .cbpx__img { position: absolute; left: 0; top: -40%; width: 100%; height: 180%; object-fit: cover; object-position: center; will-change: transform; transform: translate3d(0,0,0); backface-visibility: hidden; }
  #cbpx .cbpx__overlay { position: absolute; inset: 0; z-index: 1; background: #0B1120; opacity: .35; }
  #cbpx .cbpx__content { position: relative; z-index: 2; height: 100%; display: flex; align-items: center; justify-content: center; text-align: center; padding: 0 20px; box-sizing: border-box; }
  #cbpx .cbpx__title { margin: 0; color: #fff; font-size: 36px; line-height: 1.04; text-transform: uppercase; letter-spacing: .02em; text-shadow: 0 2px 20px rgba(0,0,0,.35); }
  @media (min-width: 750px) { #cbpx { height: 480px; } #cbpx .cbpx__title { font-size: 64px; } }
</style>

<script>
(function () {
  var el = document.getElementById('cbpx'); if (!el) return;
  var img = el.querySelector('.cbpx__img'); if (!img) return;
  var node = el.parentElement;
  while (node) {
    node.style.paddingTop = '0'; node.style.paddingBottom = '0';
    node.style.marginTop = '0'; node.style.marginBottom = '0';
    if (node.classList && node.classList.contains('shopify-section')) break;
    node = node.parentElement;
  }
  var factor = parseFloat(el.getAttribute('data-cbp-factor')) || 0.25;
  var ticking = false;
  function update() {
    ticking = false;
    var r = el.getBoundingClientRect();
    var vh = window.innerHeight || document.documentElement.clientHeight;
    if (r.bottom < -50 || r.top > vh + 50) return;
    var shift = -r.top * factor;
    var max = r.height * 0.40;
    if (shift > max) shift = max; else if (shift < -max) shift = -max;
    img.style.transform = 'translate3d(0,' + shift.toFixed(2) + 'px,0)';
  }
  function onScroll() { if (!ticking) { ticking = true; window.requestAnimationFrame(update); } }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll, { passive: true });
  update();
})();
</script>
{%- endif -%}

{%- if collection.handle == 'apto-credito-lga' -%}
<div id="cred3">
  <div class="cred3__head">
    <h2>Comprá en cuotas con crédito LGA</h2>
    <p>En 3 pasos simples — un crédito por cliente.</p>
  </div>
  <div class="cred3__steps" id="cred3steps">
    <div class="cred3__card"><span class="cred3__num">1</span><span class="cred3__ico">🛒</span><h3>Elegí tu producto</h3><p>Entrá al producto que quieras llevarte de nuestro catálogo.</p></div>
    <div class="cred3__card"><span class="cred3__num">2</span><span class="cred3__ico">💳</span><h3>Tocá el botón de crédito</h3><p>Dentro del producto, hacé click en «Pagá en cuotas con crédito LGA».</p></div>
    <div class="cred3__card"><span class="cred3__num">3</span><span class="cred3__ico">💬</span><h3>Te contactamos</h3><p>LGA evalúa tu solicitud y te escribe por WhatsApp. No pagás nada acá.</p></div>
  </div>
  <div class="cred3__dots" id="cred3dots" aria-hidden="true"><span></span><span></span><span></span></div>
  <div class="cred3__note">Hasta 24 cuotas · pago semanal, mensual o diario en efectivo · solo Tucumán</div>
</div>
<style>
  #cred3 { --teal:#0F766E; --teal-soft:#ecfdf5; max-width:1100px; margin:0 auto; padding:36px 16px; box-sizing:border-box; }
  #cred3 .cred3__head { text-align:center; margin-bottom:26px; }
  #cred3 .cred3__head h2 { margin:0 0 6px; font-size:26px; line-height:1.15; color:#0b1120; }
  #cred3 .cred3__head p { margin:0; color:#5b6472; font-size:15px; }
  #cred3 .cred3__steps { display:grid; grid-template-columns:repeat(3,1fr); gap:18px; }
  #cred3 .cred3__card { position:relative; background:#fff; border:1px solid #e6e9ee; border-radius:16px; padding:28px 20px 22px; text-align:center; box-shadow:0 6px 22px rgba(11,17,32,.05); box-sizing:border-box; }
  #cred3 .cred3__num { position:absolute; top:-14px; left:50%; transform:translateX(-50%); width:30px; height:30px; border-radius:50%; background:var(--teal); color:#fff; font-weight:700; font-size:15px; display:flex; align-items:center; justify-content:center; }
  #cred3 .cred3__ico { display:block; font-size:34px; margin:6px 0 10px; }
  #cred3 .cred3__card h3 { margin:0 0 8px; font-size:17px; color:var(--teal); }
  #cred3 .cred3__card p { margin:0; font-size:14px; color:#5b6472; line-height:1.45; }
  #cred3 .cred3__note { margin-top:22px; text-align:center; background:var(--teal-soft); color:var(--teal); font-size:13.5px; font-weight:600; padding:12px 16px; border-radius:12px; }
  #cred3 .cred3__dots { display:none; }
  @media (min-width:750px) { #cred3 .cred3__clone { display:none !important; } }
  @media (max-width:749px) {
    #cred3 .cred3__steps { grid-template-columns:none; grid-auto-flow:column; grid-auto-columns:100%; overflow-x:auto; scroll-snap-type:x mandatory; -webkit-overflow-scrolling:touch; gap:14px; padding:22px 0 6px; scrollbar-width:none; }
    #cred3 .cred3__steps::-webkit-scrollbar { display:none; }
    #cred3 .cred3__card { scroll-snap-align:center; }
    #cred3 .cred3__dots { display:flex; justify-content:center; gap:7px; margin-top:14px; }
    #cred3 .cred3__dots span { width:8px; height:8px; border-radius:50%; background:#cbd5d1; transition:background .2s, width .2s; }
    #cred3 .cred3__dots span.on { background:var(--teal); width:22px; border-radius:4px; }
    #cred3 .cred3__head h2 { font-size:22px; }
  }
</style>
<script>
(function(){
  var steps=document.getElementById('cred3steps'), dotsWrap=document.getElementById('cred3dots');
  if(!steps||!dotsWrap) return;
  var dots=dotsWrap.children, real=steps.children.length;
  var mq=window.matchMedia('(max-width:749px)');
  var timer=null, resumeT=null, idx=0, hasClone=false;
  function ensureClone(){ if(!hasClone){ var c=steps.children[0].cloneNode(true); c.className='cred3__card cred3__clone'; c.setAttribute('aria-hidden','true'); steps.appendChild(c); hasClone=true; } }
  function cw(){ var f=steps.children[0]; return f ? f.getBoundingClientRect().width + 14 : 0; }
  function goTo(i, smooth){ try{ steps.scrollTo({ left: cw()*i, behavior: smooth?'smooth':'auto' }); }catch(e){ steps.scrollLeft = cw()*i; } }
  function paint(i){ var d=((i%real)+real)%real; for(var k=0;k<dots.length;k++){ dots[k].className=(k===d?'on':''); } }
  function advance(){ idx++; goTo(idx, true); paint(idx); if(idx>=real){ setTimeout(function(){ idx=0; goTo(0,false); paint(0); }, 480); } }
  function play(){ stop(); if(mq.matches){ timer=setInterval(advance, 3200); } }
  function stop(){ if(timer){ clearInterval(timer); timer=null; } }
  function pauseResume(){ stop(); if(resumeT) clearTimeout(resumeT); resumeT=setTimeout(function(){ var i=Math.round(steps.scrollLeft/(cw()||1)); if(i>=real) i=0; idx=i; paint(idx); play(); }, 4500); }
  steps.addEventListener('pointerdown', pauseResume, {passive:true});
  steps.addEventListener('wheel', pauseResume, {passive:true});
  steps.addEventListener('touchstart', pauseResume, {passive:true});
  function boot(){ if(mq.matches){ ensureClone(); idx=0; goTo(0,false); paint(0); play(); } else { stop(); paint(0); } }
  if(mq.addEventListener) mq.addEventListener('change', boot); else if(mq.addListener) mq.addListener(boot);
  if(document.readyState==='loading'){ window.addEventListener('DOMContentLoaded', boot); } else { boot(); }
})();
</script>
{%- endif -%}
